        require(
            _minPurchaseAmount > 0,
            "Min purchase amount must be greater than 0"
        );
        uint256 oldAmount = minPurchaseAmount;
        minPurchaseAmount = _minPurchaseAmount;
        emit MinPurchaseAmountUpdated(oldAmount, _minPurchaseAmount);
    }

    /**
